function awardLevels(s){const current=level(s),rewards=[];for(let l=s.rewardLevel+1;l<=current;l++){const r=reward(l);s.coins+=r.coins;s.seeds[r.crop]+=r.seeds;s.items.fertilizer+=r.fertilizer;if(r.outfit&&!s.wardrobe.owned.includes(r.outfit))s.wardrobe.owned.push(r.outfit);if(r.furniture&&!s.house.owned.includes(r.furniture))s.house.owned.push(r.furniture);rewards.push({level:l,...r})}for(const [k,d]of Object.entries(outfits))if(d.rewardOnly&&d.level<=current&&!s.wardrobe.owned.includes(k))s.wardrobe.owned.push(k);for(const [k,d]of Object.entries(furnishings))if(d.rewardOnly&&d.level<=current&&!s.house.owned.includes(k))s.house.owned.push(k);s.rewardLevel=current;return rewards}

